source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(x == v for row in grid for x in row))
    out = [row[:] for row in grid]
    seen = set()
    noise = {0, 5, 8, 9}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color in noise or (r,c) in seen:
                continue
            q = [(r,c)]; seen.add((r,c)); cells = []
            while q:
                y,x = q.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            for y in range(min(y for y,x in cells), max(y for y,x in cells)+1):
                for x in range(min(x for y,x in cells), max(x for y,x in cells)+1):
                    out[y][x] = color
    for r in range(h):
        for c in range(w):
            if grid[r][c] in noise:
                out[r][c] = bg
    return out
'''
